public with sharing class PortalCaseController {
    @AuraEnabled(cacheable=true)
    public static List<Case> getMyCases() {
        Id contactId = [SELECT ContactId FROM User WHERE Id = :UserInfo.getUserId()].ContactId;
        return [
            SELECT Id, CaseNumber, Subject, Status, CreatedDate
            FROM Case
            WHERE ContactId = :contactId
            WITH USER_MODE
            ORDER BY CreatedDate DESC
            LIMIT 50
        ];
    }
}

public with sharing class PatientVitalsService {
    @AuraEnabled(cacheable=true)
    public static List<CareObservation> getRecentVitals(Id patientId) {
        return [
            SELECT Id, Code.Name, NumericValue, ObservedValueText,
                   UnitOfMeasure.Name, EffectiveDateTime
            FROM CareObservation
            WHERE ObservedSubjectId = :patientId
              AND ObservationStatus = 'Final'   // confirm the picklist API value in your org
              AND EffectiveDateTime = LAST_N_DAYS:90
            WITH USER_MODE
            ORDER BY EffectiveDateTime DESC
            LIMIT 50
        ];
    }
}

