trigger CaseTrigger on Case (after insert) {
    List<Case> fieldCases = new List<Case>();
    for (Case c : Trigger.new) {
        if (c.Type == 'Field Repair') fieldCases.add(c);
    }
    if (fieldCases.isEmpty()) return;

    List<WorkType> types = [SELECT Id FROM WorkType WHERE Name = 'Field Repair' LIMIT 1];
    if (types.isEmpty()) return; // or log a configuration error

    List<WorkOrder> orders = new List<WorkOrder>();
    for (Case c : fieldCases) {
        orders.add(new WorkOrder(
            CaseId = c.Id,
            AccountId = c.AccountId,
            ContactId = c.ContactId,
            AssetId = c.AssetId,
            WorkTypeId = types[0].Id,
            Subject = c.Subject
        ));
    }
    insert orders;
}

public class ScheduleAppointmentsBatch implements Database.Batchable<SObject>, Database.AllowsCallouts {
    private Id policyId;
    public ScheduleAppointmentsBatch() {
        policyId = [SELECT Id FROM FSL__Scheduling_Policy__c WHERE Name = 'Customer First' LIMIT 1].Id;
    }
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id FROM ServiceAppointment
            WHERE Status = 'None' AND ServiceTerritoryId != null
        ]);
    }
    public void execute(Database.BatchableContext bc, List<ServiceAppointment> scope) {
        FSL.ScheduleResult result = FSL.ScheduleService.schedule(policyId, scope[0].Id);
    }
    public void finish(Database.BatchableContext bc) {}
}
